package com.drogaria.backend.service;
import com.drogaria.backend.dto.PromocaoRequest; import com.drogaria.backend.entity.Promocao; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.List;
@Service public class PromocaoService { private final PromocaoRepository r; private final ProdutoRepository produtos; public PromocaoService(PromocaoRepository r,ProdutoRepository p){this.r=r;produtos=p;} public List<Promocao> listar(){return r.findAll();} public Promocao buscar(Integer id){return r.findById(id).orElseThrow(()->new ApiException("Promocao nao encontrada",HttpStatus.NOT_FOUND));} public Promocao salvar(PromocaoRequest x){if(x.getDataFim().isBefore(x.getDataInicio()))throw new ApiException("Periodo invalido",HttpStatus.BAD_REQUEST);Promocao p=new Promocao();p.setPrecoPromocional(x.getPrecoPromocional());p.setDataInicio(x.getDataInicio());p.setDataFim(x.getDataFim());p.setProduto(produtos.findById(x.getIdProduto()).orElseThrow(()->new ApiException("Produto nao encontrado",HttpStatus.NOT_FOUND)));return r.save(p);} public void excluir(Integer id){r.deleteById(id);} }